import os, re, time, sys

def _load_corpus():
    docs = {}
    for name in sorted(os.listdir('docs')):
        if not name.endswith('.txt'): continue
        docs[name] = open(os.path.join('docs', name)).read()
    return docs

def _score(question, doc_text):
    q_tokens = set(re.findall(r'[a-z_0-9]+', question.lower()))
    d_tokens = set(re.findall(r'[a-z_0-9]+', doc_text.lower()))
    return len(q_tokens & d_tokens)

def answer(question: str):
    t0 = time.time()
    docs = _load_corpus()
    ranked = sorted(docs.items(), key=lambda kv: _score(question, kv[1]), reverse=True)
    top = [name for name, txt in ranked[:2] if _score(question, txt) > 0]
    if not top:
        return {'answer': "I couldn't find anything relevant.", 'cited_docs': [], 'latency_ms': int((time.time() - t0) * 1000)}
    body = '\n\n'.join(docs[name] for name in top)
    return {'answer': body.strip()[:600], 'cited_docs': top, 'latency_ms': int((time.time() - t0) * 1000)}

if __name__ == '__main__':
    q = ' '.join(sys.argv[1:])
    print(answer(q))
